// VALIDATE SCOUT SETUP
// Stops the run before the Notion query, and therefore before any Anthropic
// request, when configuration is missing or out of range.
const cfg = $('Scout Setup').first().json;
const problems = [];

const databaseId = (cfg.notionDatabaseId || '').toString().trim();
if (!databaseId) {
  problems.push('notionDatabaseId is empty. Paste the id of your Notion signal map database.');
}

const model = (cfg.anthropicModel || '').toString().trim();
if (!model) {
  problems.push('anthropicModel is empty. Set the Anthropic model id to draft with.');
}

// One model call per row, so the batch size is also the per-run spend ceiling.
const batchSize = Number(cfg.batchSize);
if (!Number.isInteger(batchSize) || batchSize < 1 || batchSize > 50) {
  problems.push('batchSize must be a whole number from 1 to 50.');
}

if (problems.length > 0) {
  throw new Error('Scout Setup is not configured correctly. ' + problems.join(' '));
}

return [{ json: { validated: true, batchSize } }];

// PREP ROWS FOR DRAFTING
// One Anthropic request per row whose next action is something a human would
// actually write. Monitor and Ignore rows never need a draft, so they are
// skipped here rather than filtered in Notion.
const cfg = $('Scout Setup').first().json;
const model = (cfg.anthropicModel || '').toString().trim();
const batchSize = Number(cfg.batchSize);

const DRAFTABLE_ACTIONS = ['Comment', 'DM', 'Connect'];

const SYSTEM = [
  'You draft short outreach for a HubSpot data and automation consultancy.',
  'Voice: peer operator, diagnostic, never pitchy. No emojis, no hashtags, no links.',
  'You are given a SIGNAL describing someone\'s HubSpot pain, and an ACTION. Write exactly one message:',
  '- ACTION Comment: two or three sentences of public reply that add a diagnostic distinction, name a hidden cost, or ask an operator-level question. No pitch.',
  '- ACTION DM: a low-friction direct message that references their issue and asks ONE diagnostic question. Do not ask for a call or a meeting.',
  '- ACTION Connect: a single warm sentence referencing the shared topic.',
  'Return ONLY the message text. No preamble, no surrounding quotes, under 90 words.'
].join('\n');

function props(page) { return (page && page.properties) || {}; }
function sel(page, key) { const v = props(page)[key]; return (v && v.select && v.select.name) || ''; }
function textOf(page, key) {
  const v = props(page)[key];
  return ((v && v.rich_text) || []).map((x) => x.plain_text || '').join('');
}
function multiOf(page, key) {
  const v = props(page)[key];
  return ((v && v.multi_select) || []).map((x) => x.name).join(', ');
}
function titleOf(page) {
  const t = (props(page).Name && props(page).Name.title) || [];
  return t.map((x) => x.plain_text || '').join('');
}

let pages = [];
try { pages = $input.first().json.results || []; } catch (e) { pages = []; }

const out = [];

for (const page of pages) {
  if (out.length >= batchSize) break;
  const action = sel(page, 'Next action');
  if (!DRAFTABLE_ACTIONS.includes(action)) continue;
  if (!page.id) continue;

  const userContent = [
    'ACTION: ' + action,
    'SIGNAL: ' + textOf(page, 'Signal'),
    'BEST ANGLE: ' + textOf(page, 'Best angle'),
    'PAIN AREA: ' + multiOf(page, 'Pain area'),
    'PERSON: ' + titleOf(page)
  ].join('\n');

  out.push({ json: {
    pageId: page.id,
    action,
    name: titleOf(page),
    _anthropicBody: {
      model,
      max_tokens: 300,
      system: SYSTEM,
      messages: [{ role: 'user', content: userContent }]
    }
  }});
}

return out;

// BUILD THE NOTION PATCH
// Pairs each Anthropic response with its row by index. A response Scout cannot
// read is not an error and is not a silent drop: the row is left exactly as it
// was and the run emits a "Needs review" item naming the page, so the operator
// can see what failed without the workflow inventing text.
const sources = $('Prep Rows').all();
const inputs = $input.all();
const out = [];

for (let i = 0; i < inputs.length; i++) {
  const src = (sources[i] && sources[i].json) || {};
  const response = inputs[i].json || {};

  let text = '';
  try { text = (response.content || []).map((c) => c.text || '').join('').trim(); }
  catch (e) { text = ''; }

  if (!src.pageId) continue;

  if (!text) {
    out.push({ json: {
      draftReady: false,
      status: 'Needs review',
      pageId: src.pageId,
      name: src.name,
      action: src.action,
      reason: 'The model returned no usable text. The Notion row was left unchanged.'
    }});
    continue;
  }

  out.push({ json: {
    draftReady: true,
    pageId: src.pageId,
    name: src.name,
    action: src.action,
    _url: 'https://api.notion.com/v1/pages/' + src.pageId,
    _notionBody: { properties: { 'Draft': { rich_text: [{ text: { content: text.slice(0, 1900) } }] } } }
  }});
}

return out;
